<span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">pub</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> check_source</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">src</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#6F42C1;">str</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> Result</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&lt;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#6F42C1;">bool</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> FormatError</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&gt;;</span></span>
